/* @author MILO-GAO(高振銘)@2020 */ package page2020.flow;import java.util.Set;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.App;import page2020.core.Flow;import page2020.core.Form;import page2020.core.Log;import page2020.unit.Ualert;import page2020.unit.Ubox;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.C3;import page2020.view.Child;import page2020.view.Element;import page2020.view.H5;import page2020.view.Text;import page2020.view.bs4.B4button;import page2020.view.bs4.B4card;import page2020.view.bs4.B4color.Bg;import page2020.view.bs4.B4ctrl;import page2020.view.bs4.B4element;import page2020.view.bs4.B4show.D;import page2020.view.bs4.B4text.TextX;import page2020.view.css3.C3color.Red;import page2020.view.css3.C3color.White;import page2020.view.css3.C3color.Yellow;import page2020.view.css3.C3show.Display;import page2020.view.html5.H5span;public class FormFlow extends LayoutFlow {	private static Logger log = LoggerFactory.getLogger(FormFlow.class);	private int cards = 0;	private int containers = 0;	protected int boxes = 0;	private int operates = 0;	protected boolean operateJS = false;	private boolean uploadJS = false;	@Override	public Flow automate() {		super.automate();		super.forms.forEach((name, child) -> this.wrap(child));		if (super.code == 1 || super.code == 2 || super.code == 3) {			super.hideButtons("home.button");		}		Set<String> scripts = super.page.getScripts();		if (this.operateJS) {				scripts.add(Path.page2020 + "operate.js");		}		super.page.getScripts().add(Path.page2020 + "form.js");		if (this.uploadJS) {			scripts.add(Path.page2020 + "upload.js");		}		if (this.boxes > 0) {			scripts.add(Path.page2020 + "box.js");		}		super.page.selector("span." + Form.errors,			C3.text.whiteSpace(false),			C3.show.display(Display.inlineBlock), C3.color(Red.Red), C3.bg(Yellow.LightYellow), 			C3.margin("0.125rem 0 0 0.25rem"), C3.padding("0 0.5rem"), C3.border("1px solid pink"), 			C3.border.radius("1rem")		);		super.page.selector("select." + B4ctrl.disabled, C3.bg("#e9ecef"));		super.page.selector("form hr", C3.margin.top("0.5rem"), C3.margin.bottom("0.5rem"));		super.page.selector("form .form-group", C3.margin("0 0 0.5rem 0"));		super.page.selector("form .form-group label", C3.margin("0"));		if (this.boxes > 0) {			Ubox.selector(super.page);		}		if (Log.flow) {			log.info(super.logName + "card=" + this.cards + ", containers=" + this.containers				+ ", boxes=" + this.boxes + ", operates=" + this.operates);		}		return this;	}		private void wrap(Child child) {		Form form = (Form) child.getContent();		Element<?, ?> wrapper1 = null;		Element<?, ?> wrapper2 = null;		Element<?, ?> wrapper3 = null;		if (form.isCard()) {			wrapper1 = this.card(form);			this.cards += 1;		} else {			wrapper1 = form;		}		if (super.page.getUi() == 2 && (! form.isBean())) {			form.box();			String name = super.page.getApp().getName() + this.path(form.getCode());			wrapper1 = new Ubox(name, form.getBox(), new Ualert(form.getName()), form);			this.boxes += 1;						}		if (EmptyUtil.not(form.getOperate())) {			wrapper2 = this.operate(form.getOperate(), wrapper1);			this.operates += 1;					} else {			wrapper2 = wrapper1;		}		if (form.isContainer()) {			wrapper3 = B4.container().append(wrapper2);			this.containers += 1;		} else {			wrapper3 = wrapper2;		}				if (form.isOperateJS()) {			this.operateJS = true;		}		if (form.isUploadJS()) {			this.uploadJS = true;		}		child.getElement().set(child.getIndex(), wrapper3);	}	private B4card card(Form form) {		String background = null;		Text icon = null;		if (form.isBean()) {			background = Bg.info;			icon = App.icon("card.query");					} else {						switch (super.code) {			case Code.submit:				background = Bg.primary;				icon = App.icon("card.submit");				break;			case Code.insert:				background = Bg.success;				icon = App.icon("card.insert");				break;			case Code.update:				background = Bg.warning;				icon = App.icon("card.update");				break;			case Code.deleted:				background = Bg.danger;				icon = App.icon("card.delete");				break;			case Code.detail:				background = Bg.info;				icon = App.icon("card.detail");				break;			case Code.history:				background = Bg.info;				icon = App.icon("card.history");				break;			default:				background = Bg.secondary;				icon = App.icon("form");				break;						}		}		B4card card = B4.card().cssClass("m-0", "mb-2").css(C3.padding("2px"));		if (background != null) {			card.cssClass(background);		}		H5span span = H5.span().cssClass("ml-1");		String classKey = App.classKey(form.getName());		if (classKey != null) {			span.code(classKey);		} else {			log.error("FormFlow: '" + form.getName() + "' is NOT in messages.properties !");		}		card.header().cssClass("m-0", "px-2", "py-0")			.css(C3.color(White.White))			.append(icon, span);		card.body().cssClass("m-0", "px-3", "pt-1", "pb-0").css(C3.bg(White.White));		if (! form.isBean()) {			card.body().append(new Ualert(form.getName()));		}		card.body().append(form);		if (super.page.getUi() >= 1) {			card.boxes().css(C3.border.radius("1rem"));			card.header().css(C3.border("none"));			card.body().css(C3.border.radius("1rem"));		}		return card;	}	private String path(int code) {		switch (code) {		case Code.submit:			return "/submit";		case Code.insert:			return "/insert";		case Code.update:			return "/update";		case Code.deleted:			return "/delete";		case Code.detail:			return "/detail";		case Code.history:			return "/history";		default:			return "";		}	}	private Element<?, ?> operate(String argument, Element<?, ?> wrapper1) {		Element<?, ?> wrapper2 = null;		String[] tokens = argument.split(";");		String[] btnNames = tokens[0].split(",");		B4element container = B4.element().cssClass("text-center", "text-md-right").data("operate", "button");		for (int i=0; i < btnNames.length; i++) {			B4button button = App.button(btnNames[i]);			if (button != null) {				button					.name(null)					.data(PageKey.operate, btnNames[i])					.cssClass(TextX.nowrap)					.css(						C3.padding("0.25rem 1rem"), 						C3.margin("0.375rem 0.125rem 0 0.125rem"), 						C3.border.radius("1rem")					);				container.append(button);								}		}		wrapper2 = B4.row(true).append(			B4.col().device(tokens[1]).append(wrapper1),				B4.col().device(tokens[2]).append(container)			);		wrapper2.css(C3.margin.bottom(tokens[3]));		super.buttonBox.cssClass(D.none);		return wrapper2;	}	}